class Solution {
public:
    void dfs(int pos, int removed, vector<pair<int,int>>& cells,
             vector<vector<char>>& kept, int m, int n, int& best) {
        if (removed >= best) return;
        if (pos == (int)cells.size()) { best = removed; return; }
        auto [i, j] = cells[pos];
        static const int dr[4] = {1, -1, 0, 0}, dc[4] = {0, 0, 1, -1};
        dfs(pos + 1, removed + 1, cells, kept, m, n, best);
        bool ok = true;
        for (int d = 0; d < 4 && ok; d++) {
            int x = i + dr[d], y = j + dc[d];
            if (x >= 0 && x < m && y >= 0 && y < n && kept[x][y]) ok = false;
        }
        if (ok) {
            kept[i][j] = 1;
            dfs(pos + 1, removed, cells, kept, m, n, best);
            kept[i][j] = 0;
        }
    }
    int minimumOperations(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<pair<int,int>> cells;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (grid[i][j]) cells.push_back({i, j});
        int best = cells.size();
        vector<vector<char>> kept(m, vector<char>(n, 0));
        dfs(0, 0, cells, kept, m, n, best);
        return best;
    }
};

