class Solution {
    private int best;
    private int[][] cells;
    private boolean[][] kept;

    public int minimumOperations(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int cnt = 0;
        for (int[] row : grid) for (int v : row) if (v == 1) cnt++;
        cells = new int[cnt][2];
        int idx = 0;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (grid[i][j] == 1) { cells[idx][0] = i; cells[idx][1] = j; idx++; }
        best = cnt;
        kept = new boolean[m][n];
        dfs(0, 0, m, n);
        return best;
    }

    private void dfs(int pos, int removed, int m, int n) {
        if (removed >= best) return;
        if (pos == cells.length) { best = removed; return; }
        int i = cells[pos][0], j = cells[pos][1];
        dfs(pos + 1, removed + 1, m, n);
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        boolean ok = true;
        for (int[] d : dirs) {
            int x = i + d[0], y = j + d[1];
            if (x >= 0 && x < m && y >= 0 && y < n && kept[x][y]) { ok = false; break; }
        }
        if (ok) {
            kept[i][j] = true;
            dfs(pos + 1, removed, m, n);
            kept[i][j] = false;
        }
    }
};

