class Solution:
    def minimumOperations(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        match = {}

        def aug(i, j, seen):
            for x, y in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
                if 0 <= x < m and 0 <= y < n and grid[x][y] == 1 and (x, y) not in seen:
                    seen.add((x, y))
                    if (x, y) not in match or aug(*match[(x, y)], seen):
                        match[(x, y)] = (i, j)
                        return True
            return False

        ans = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1 and (i + j) % 2 == 0:
                    if aug(i, j, set()):
                        ans += 1
        return ans

