class Solution {
public:
    int m, n, stamp;
    vector<int> matchR, seen;

    bool aug(const vector<vector<int>>& g, int i, int j) {
        static const int dr[4] = {1, -1, 0, 0}, dc[4] = {0, 0, 1, -1};
        for (int d = 0; d < 4; d++) {
            int x = i + dr[d], y = j + dc[d];
            if (x < 0 || x >= m || y < 0 || y >= n || !g[x][y]) continue;
            int v = x * n + y;
            if (seen[v] == stamp) continue;
            seen[v] = stamp;
            if (matchR[v] < 0 || aug(g, matchR[v] / n, matchR[v] % n)) {
                matchR[v] = i * n + j;
                return true;
            }
        }
        return false;
    }

    int minimumOperations(vector<vector<int>>& grid) {
        m = grid.size(); n = grid[0].size();
        matchR.assign(m * n, -1);
        seen.assign(m * n, 0);
        stamp = 0;
        int ans = 0;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (grid[i][j] == 1 && (i + j) % 2 == 0) {
                    stamp++;
                    if (aug(grid, i, j)) ans++;
                }
        return ans;
    }
};

