class Solution {
    private int m, n, stamp;
    private int[] matchR, seen;

    public int minimumOperations(int[][] grid) {
        m = grid.length; n = grid[0].length;
        matchR = new int[m * n];
        Arrays.fill(matchR, -1);
        seen = new int[m * n];
        stamp = 0;
        int ans = 0;
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (grid[i][j] == 1 && (i + j) % 2 == 0) {
                    stamp++;
                    if (aug(grid, i, j)) ans++;
                }
        return ans;
    }

    private boolean aug(int[][] g, int i, int j) {
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        for (int[] d : dirs) {
            int x = i + d[0], y = j + d[1];
            if (x < 0 || x >= m || y < 0 || y >= n || g[x][y] == 0) continue;
            int v = x * n + y;
            if (seen[v] == stamp) continue;
            seen[v] = stamp;
            if (matchR[v] < 0 || aug(g, matchR[v] / n, matchR[v] % n)) {
                matchR[v] = i * n + j;
                return true;
            }
        }
        return false;
    }
};

