    const aug = (i, j) => {
        for (const [dx, dy] of dirs) {
            const x = i + dx, y = j + dy;
            if (x < 0 || x >= m || y < 0 || y >= n || grid[x][y] === 0) continue;
            const v = x * n + y;
            if (seen[v] === stamp) continue;
            seen[v] = stamp;
            if (matchR[v] < 0 || aug(Math.floor(matchR[v] / n), matchR[v] % n)) {
                matchR[v] = i * n + j;
                return true;
            }
        }
        return false;
    };
    let ans = 0;
    for (let i = 0; i < m; i++)
        for (let j = 0; j < n; j++)
            if (grid[i][j] === 1 && (i + j) % 2 === 0) {
                stamp++;
                if (aug(i, j)) ans++;
            }
    return ans;
};
